// Logo set on load based on theme — SVG variants for all logo placements
var _initTheme=localStorage.getItem('ege_theme')||'dark';
var _initLogoSrc=_initTheme==='dark'?'brand_assets/logo_if_bg_color.svg':'brand_assets/logo_if_bg_white.svg';
document.querySelectorAll('#login-logo-img,#sb-logo-img,#portal-logo-img').forEach(function(el){
  el.src=_initLogoSrc;
  el.style.mixBlendMode='normal';
  el.style.filter='none';
});

// ════ XSS KORUMA ════
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

// ════ DATA ════
const DB={
  load(k,d){try{return JSON.parse(localStorage.getItem(k)??'null')??d}catch{return d}},
  save(k,v){localStorage.setItem(k,JSON.stringify(v))},
  pload(k,d){return DB.load('ege_'+(currentPortal||'servis')+'_'+k,d)},
  psave(k,v){DB.save('ege_'+(currentPortal||'servis')+'_'+k,v)}
};
let currentPortal=''; // 'servis' | 'satis' | 'stok'
const AKSESUAR_LIST=['Yazıcı','Yazıcı Batarya','Batarya','A. Şarj Aleti','Yazıcı Şarj Aleti','Bağlantı Kablo'];
const DURUM_LIST=['Cihaz Kabul','Arıza Tespitinde','Yanıt Bekleniyor','Onarımda','Teslim Edildi','Reddedildi','İşlemsiz İade'];
const DURUM_COLORS=['#2dd4bf','#f59e0b','#a78bfa','#3d9bc4','#4ade80','#f87171','#f97316'];
const DURUM_CLASS={'Cihaz Kabul':'badge-yeni','Arıza Tespitinde':'badge-sf','Yanıt Bekleniyor':'badge-onay-bekl','Onarımda':'badge-onaylandi','Teslim Edildi':'badge-teslim','Reddedildi':'badge-reddedildi','İşlemsiz İade':'badge-iade'};

let state={
  currentUser:null,prevPage:'servisler',activeTeklifId:null,
  users:[],
  servisler:[],
  teklifler:[],
  musteriler:DB.pload('musteriler',[]),
  urunler:[],
  urunKategoriler:DB.pload('urunKategoriler',['Cihaz','Yazılım','Aksesuar','Sarf Malzeme','Diğer']),
  settings:{firma:'',tel:'',faks:'',adres:'',email:'',web:'',parametreler:[]},
  sortCol:'kayitNo',sortDir:'desc'
};
let sfAksesuarlar=[];
let teklifItems=[];

function saveAll(){
  if(currentPortal==='stok') return;
  var keys=['musteriler','urunKategoriler'];
  keys.forEach(function(k){if(state[k]!==undefined)DB.psave(k,state[k]);});
}

// ════ UTILS ════
const today=()=>new Date().toISOString().slice(0,10);
function fmtDate(d){if(!d)return'—';try{return new Date(d+'T12:00:00').toLocaleDateString('tr-TR')}catch{return d}}
function fmtTL(v){if(v===''||v==null)return'—';return new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',minimumFractionDigits:2}).format(v)}
function fmtNum(v){if(v===''||v==null)return'—';return new Intl.NumberFormat('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v)}
function nextTN(){const p=(state.settings&&state.settings.teklifPrefix)||'TKL';const d=parseInt((state.settings&&state.settings.teklifDigits)||5);const n=state.teklifler.map(t=>parseInt((t.teklifNo||'').replace(p,''))||0);return p+String((n.length?Math.max(...n):0)+1).padStart(d,'0')}
function durumBadge(d){return`<span class="badge ${DURUM_CLASS[d]||''}">${d||'—'}</span>`}
function calcTeklifToplam(t){return(t.satirlar||[]).reduce(function(a,s){return a+(s.miktar*s.birimFiyat)},0)}

